#include "window.hpp"
#include "nect/io.hpp"
#include <QApplication>
#include <QCheckBox>
#include <QDockWidget>
#include <QFile>
#include <QPlainTextEdit>
#include <QProcess>
#include <QPushButton>
#include <QScrollArea>
#include <QSettings>
#include <QStatusBar>
#include <QTemporaryDir>
#include <QTest>
#include <iostream>
#include <stdexcept>
using namespace nect;
using namespace nect::desktop;
namespace {
int checks=0;
const char* guide_ids[]={"guide-x","guide-y"};
const char* sources[]={"10\n+ 0.5","20\n+ 0.5"};
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(15);}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error(("Missing control: "+name).toStdString());}
QString name(int field,const char* suffix){
 if(QString(suffix)=="-expression")return "guide-position-expression-"+QString(guide_ids[field]);
 if(QString(suffix)=="-apply-expression")return "guide-position-apply-expression-"+QString(guide_ids[field]);
 return "guide-position-"+QString(guide_ids[field]);
}
void reveal(QWidget* c){for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(c->isVisible(),"Exact production control visible");}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full Document native-valid BEFORE Window");}
Document fixture(int mode){
 auto d=empty_document("guide-draft-"+std::to_string(mode),"composition","board");auto& comp=d.compositions.front();auto& b=comp.artboards.front();b.width=1200;b.height=900;
 b.layout=ArtboardLayout{Margin{10.123456789012345,20.234567890123456,30.345678901234567,40.456789012345678},Grid{"grid",{15.123456789012345,20.234567890123456,1000.1234567890123,800.23456789012345},3,2,7.345678901234567,8.456789012345678}};
 comp.guides={{"guide-x","Vertical","x",10.123456789012345},{"guide-y","Horizontal","y",20.234567890123456},{"peer","Untouched peer","x",30.345678901234567}};comp.guides[2].position_expression=Expression{"30 + 0.25",1};
 Object o;o.id="sentinel";o.kind=Kind::path;Contour c;c.id="contour";Point p;p.id="point";p.x.literal=51.25;p.y.literal=-21.75;c.points={p};o.contours={c};d.objects.emplace(o.id,o);comp.roots={o.id};valid(d);return d;
}
Document wanted(const Document& initial,int field){auto d=initial;d.compositions.front().guides[field].position_expression=Expression{sources[field],1};valid(d);return d;}
std::vector<Command> command(int field,const std::string& body=""){return {SetGuidePositionExpression{{guide_ids[field],"","guide.position"},{body.empty()?sources[field]:body,1},false}};}
Session gesture_commit(const Document& d,int field){Session expected(d);expected.begin_gesture(0);expected.update_gesture(command(field));expected.commit_gesture();return expected;}
void same(const Session& a,const Session& b){if(!(a.document()==b.document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation()))std::cerr<<"Snapshot doc="<<(a.document()==b.document())<<" history="<<(a.history()==b.history())<<" rev="<<a.revision()<<"/"<<b.revision()<<" active="<<a.gesture_active()<<"/"<<b.gesture_active()<<" gen="<<a.gesture_generation()<<"/"<<b.gesture_generation()<<"\n";check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Full canonical Session equals independent pre-Window expectation");}
void write(const QString& path,const Document& d){QFile f(path);const auto bytes=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(bytes.data(),bytes.size())==static_cast<qint64>(bytes.size()),"Independent native oracle retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
QString prefix(const QString& root,int mode){return root+"/mode-"+QString::number(mode);}
void open(Window& w,const Document& d){w.host.session=Session(d);w.host.edited();w.canvas->set_active_artboard("composition","board",false);w.resize(1400,1000);w.show();w.activateWindow();events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();auto* edit=control<QPushButton>(w,"artboard-edit");reveal(edit);edit->click();events();}
void draft(Window& w,int field,const QString& body=QString{}){const auto text=body.isNull()?QString(sources[field]):body;auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_A,Qt::ControlModifier);const auto lines=text.split('\n');for(int i=0;i<lines.size();++i){if(i)QTest::keyClick(editor,Qt::Key_Return);QTest::keyClicks(editor,lines[i]);}events();check(editor->toPlainText()==text,"Exact Guide source draft retained");}
void cancel(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Escape);events();}
void apply(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Return,Qt::ControlModifier);events();}
void reset(Window& w,const Document& d,const QString& key){w.host.session=Session(d);w.host.session_id+=key;w.host.edited();events();}
void cold(const QString& root,int mode){const auto d=wanted(fixture(mode),mode);Session expected(d);const auto path=prefix(root,mode);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-cold",std::make_unique<FolderLibrary>(settings),&settings);w.host.open(path+"-cold-input.nect");same(w.host.session,expected);w.host.save(path+"-resaved.nect");w.host.flush();same(w.host.session,expected);check(read(path+"-cold-input.nect")==read(path+"-expected.nect")&&read(path+"-resaved.nect")==read(path+"-expected.nect"),"Separate cold exact expression native bytes");QTest::qWait(120);}

void flow(const QString& root,int mode){
 const int field=mode,other=1-field;const auto initial=fixture(mode),intended=wanted(initial,field);Session before(initial),direct(initial);direct.apply(command(field),0);auto committed=gesture_commit(initial,field);check(direct.document()==intended&&committed.document()==intended&&direct.history()==committed.history()&&direct.revision()==committed.revision(),"Independent full intended Guide authoring and canonical gesture expectation BEFORE Window");
 auto incoming=initial.compositions.front().artboards.front();incoming.name="External revision";Session newer(initial);newer.apply({UpdateArtboard{"composition",incoming}},0);auto newer_intended=intended;newer_intended.compositions.front().artboards.front().name=incoming.name;valid(newer_intended);auto refreshed_commit=newer;refreshed_commit.begin_gesture(1);refreshed_commit.update_gesture(command(field));refreshed_commit.commit_gesture();check(refreshed_commit.document()==newer_intended,"Independent fresh after Cancel canonical Guide gesture expectation BEFORE Window");
 auto replacement=initial;replacement.id+="-replacement";valid(replacement);Session replaced(replacement);auto foreign=before;foreign.begin_gesture(0);foreign.update_gesture({UpdateArtboard{"composition",incoming}});
 Session invalid(initial);QString invalid_error;invalid.begin_gesture(0);try{invalid.update_gesture(command(field,"1 / 0"));}catch(const Error& e){invalid_error=QString::fromStdString(e.code);}invalid.cancel_gesture();check(!invalid_error.isEmpty()&&invalid.document()==before.document()&&invalid.history()==before.history()&&invalid.revision()==0&&!invalid.gesture_active(),"Independent invalid canonical Guide gesture refusal BEFORE Window");
 const auto path=prefix(root,mode);write(path+"-initial.nect",initial);write(path+"-expected.nect",intended);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);open(w,initial);same(w.host.session,before);draft(w,field);draft(w,other);same(w.host.session,before);auto* source=control<QPlainTextEdit>(w,name(field,"-expression"));check(source->parentWidget()->grab().save(path+"-draft-before-refresh.png"),"Actual pending Guide source render retained");
 w.host.save(path+"-draft-save.nect");w.host.flush();events();same(w.host.session,before);check(read(path+"-draft-save.nect")==read(path+"-initial.nect"),"Pending Guide source excluded from actual native Save after processed refresh");
 source=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(source);check(source->parentWidget()->grab().save(path+"-draft-after-refresh.png"),"Actual refreshed Guide source render retained");std::cout<<"REFRESH field="<<field<<" source="<<source->toPlainText().toStdString()<<" expected="<<sources[field]<<"\n";check(source->toPlainText()==sources[field],"Same Session native Save and processed UI refresh retains exact pending Guide source");check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Sibling pending Guide source survives refresh");
 apply(w,field);same(w.host.session,committed);check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Guide source commit preserves sibling pending draft");apply(w,other);same(w.host.session,committed);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Sibling pending Guide draft retains original revision");w.host.save(path+"-saved.nect");w.host.flush();events();same(w.host.session,committed);check(QFile::copy(path+"-saved.nect",path+"-cold-input.nect"),"Actual saved source retained before later edits");QProcess child;child.start(QCoreApplication::applicationFilePath(),{"--cold",root,QString::number(mode)});check(child.waitForStarted(5000),"Owned cold starts");if(!child.waitForFinished(15000)){child.kill();child.waitForFinished();throw std::runtime_error("Owned cold deadline");}std::cout<<child.readAllStandardOutput().toStdString();std::cerr<<child.readAllStandardError().toStdString();check(child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"Separate cold Guide native acceptance passes");
 w.host.session.undo(w.host.session.revision());committed.undo(committed.revision());w.host.edited();events();same(w.host.session,committed);check(w.host.session.document()==initial,"One Undo restores full Guide authored sources/literals/IDs");check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Committed Guide draft does not resurrect after Undo");w.host.session.redo(w.host.session.revision());committed.redo(committed.revision());w.host.edited();events();same(w.host.session,committed);
 reset(w,initial,"-cancel");draft(w,field);draft(w,other);w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Same Session edited notification retains pending source");cancel(w,field);same(w.host.session,before);w.host.edited();events();check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Escape discards only own pending Guide source and stays cleared");check(control<QPlainTextEdit>(w,name(other,"-expression"))->toPlainText()==sources[other],"Escape preserves sibling Guide draft");cancel(w,other);same(w.host.session,before);
 reset(w,initial,"-new-revision");draft(w,field);w.host.session.apply({UpdateArtboard{"composition",incoming}},0);w.host.edited();events();same(w.host.session,newer);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Changed revision retains Guide source for inspection");apply(w,field);same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Retained Guide draft cannot acquire fresh revision through rebuild");control<QPushButton>(w,name(field,"-apply-expression"))->click();events();same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Existing Guide Apply button shares stale source refusal");cancel(w,field);draft(w,field);apply(w,field);same(w.host.session,refreshed_commit);
 reset(w,initial,"-changed-session");draft(w,field);w.host.session_id+="-new";w.host.edited();events();same(w.host.session,before);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Source draft cannot transfer to replacement Session");
 reset(w,initial,"-changed-document");draft(w,field);w.host.session=Session(replacement);w.host.edited();events();same(w.host.session,replaced);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Same Session/revision draft cannot transfer to replacement Document");
 reset(w,initial,"-invalid");draft(w,field,"1 / 0");w.host.edited();events();apply(w,field);same(w.host.session,invalid);check(w.statusBar()->currentMessage().contains(invalid_error),"Invalid retained Guide source refuses canonical command");w.host.edited();events();same(w.host.session,invalid);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()=="1 / 0","Invalid source remains editable after refresh");
 reset(w,initial,"-foreign");draft(w,field);w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",incoming}});w.host.edited();events();apply(w,field);same(w.host.session,foreign);check(w.statusBar()->currentMessage().contains("GESTURE_ACTIVE"),"Guide source Apply refuses foreign gesture");cancel(w,field);same(w.host.session,foreign);check(w.statusBar()->currentMessage().contains("GESTURE_ACTIVE")&&control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==sources[field],"Guide source Cancel refuses and preserves foreign gesture and draft");w.host.session.cancel_gesture();cancel(w,field);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText().isEmpty(),"Guide Cancel clears own view after caller finishes");
}

}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";if(argc==4&&std::string(argv[1])=="--cold")cold(QString::fromLocal8Bit(argv[2]),std::stoi(argv[3]));else{QTemporaryDir temporary;check(temporary.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GUIDE_EXPRESSION_DRAFT_ROOT"),root=requested.isEmpty()?temporary.path():requested;int failures=0;for(int mode=0;mode<2;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Independent expression key cases failed: "+std::to_string(failures));}std::cout<<"PASS Guide source draft refresh "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Guide source draft refresh "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
